"use strict";

const crypto = require("crypto");
const fs = require("fs");
const path = require("path");

exports.summarize = function summarize(root) {
  const lock = JSON.parse(fs.readFileSync(path.join(root, "package-lock.json"), "utf8"));
  const packageKeys = Object.keys(lock.packages || {}).filter(Boolean).sort();
  const integrity = packageKeys.map((key) => lock.packages[key].integrity || "").join("|");
  const digest = crypto.createHash("sha1").update(integrity).digest("hex").slice(0, 8);
  return `lockv2:${lock.lockfileVersion}:${packageKeys.length}:${digest.length}`;
};
